"""Tables. Money is BIGINT paise, times are timestamptz, ids are UUID v7 generated by the app.

`events`, `score_snapshots`, `audit_log`, `decisions` and `outcomes` are append-only: a trigger rejects UPDATE,
DELETE and TRUNCATE.
Rows are keyed by internal user id only; no names, phone numbers or ID numbers live here.
"""

from datetime import date, datetime
from typing import Any
from uuid import UUID

from sqlalchemy import (
    BigInteger,
    Boolean,
    CheckConstraint,
    Date,
    DateTime,
    Float,
    ForeignKey,
    Identity,
    Index,
    Integer,
    SmallInteger,
    Text,
    func,
    text,
)
from sqlalchemy.dialects.postgresql import ARRAY, JSONB
from sqlalchemy.dialects.postgresql import UUID as PgUUID
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column

APPEND_ONLY_TABLES = ("events", "score_snapshots", "audit_log", "decisions", "outcomes")

TZ = DateTime(timezone=True)


class Base(DeclarativeBase):
    type_annotation_map = {UUID: PgUUID(as_uuid=True), dict[str, Any]: JSONB, datetime: TZ}


class User(Base):
    __tablename__ = "users"
    id: Mapped[UUID] = mapped_column(primary_key=True)
    created_at: Mapped[datetime]
    kyc_level: Mapped[str] = mapped_column(Text, server_default="none")
    college_verified: Mapped[bool] = mapped_column(Boolean, server_default=text("false"))
    phone_first_seen_at: Mapped[date | None] = mapped_column(Date)
    status: Mapped[str] = mapped_column(Text, server_default="active")
    synthetic: Mapped[bool] = mapped_column(Boolean, server_default=text("false"))


class Vendor(Base):
    __tablename__ = "vendors"
    id: Mapped[UUID] = mapped_column(primary_key=True)
    category: Mapped[str | None] = mapped_column(Text)
    onboarded_at: Mapped[datetime]
    status: Mapped[str] = mapped_column(Text, server_default="active")
    synthetic: Mapped[bool] = mapped_column(Boolean, server_default=text("false"))


class Loan(Base):
    __tablename__ = "loans"
    id: Mapped[UUID] = mapped_column(primary_key=True)
    user_id: Mapped[UUID] = mapped_column(ForeignKey("users.id"), index=True)
    principal: Mapped[int | None] = mapped_column(BigInteger)
    fees: Mapped[int | None] = mapped_column(BigInteger)
    outstanding: Mapped[int | None] = mapped_column(BigInteger)
    due_date: Mapped[date | None] = mapped_column(Date)
    state: Mapped[str] = mapped_column(Text)
    opened_at: Mapped[datetime | None]
    closed_at: Mapped[datetime | None]
    paid_in_full_at: Mapped[datetime | None]
    closure_type: Mapped[str | None] = mapped_column(Text)
    max_dpd: Mapped[int] = mapped_column(Integer, server_default="0")
    synthetic: Mapped[bool] = mapped_column(Boolean, server_default=text("false"))
    updated_at: Mapped[datetime] = mapped_column(server_default=func.now())


class Repayment(Base):
    __tablename__ = "repayments"
    id: Mapped[UUID] = mapped_column(primary_key=True)  # the event_id that reported it
    loan_id: Mapped[UUID] = mapped_column(ForeignKey("loans.id"), index=True)
    amount: Mapped[int] = mapped_column(BigInteger)
    paid_at: Mapped[datetime]
    rail: Mapped[str] = mapped_column(Text)


class PaymentAttempt(Base):
    __tablename__ = "payment_attempts"
    id: Mapped[UUID] = mapped_column(primary_key=True)  # the event_id that reported it
    loan_id: Mapped[UUID] = mapped_column(ForeignKey("loans.id"), index=True)
    amount: Mapped[int] = mapped_column(BigInteger)
    status: Mapped[str] = mapped_column(Text)
    failure_class: Mapped[str | None] = mapped_column(Text)
    rail: Mapped[str] = mapped_column(Text)
    attempted_at: Mapped[datetime]


class Event(Base):
    __tablename__ = "events"
    event_id: Mapped[UUID] = mapped_column(primary_key=True)
    idempotency_key: Mapped[str] = mapped_column(Text, unique=True)
    type: Mapped[str] = mapped_column(Text)
    user_id: Mapped[UUID]
    loan_id: Mapped[UUID | None]
    occurred_at: Mapped[datetime]
    received_at: Mapped[datetime] = mapped_column(server_default=func.now())
    source: Mapped[str] = mapped_column(Text)
    schema_version: Mapped[int] = mapped_column(SmallInteger)
    synthetic: Mapped[bool] = mapped_column(Boolean)
    payload: Mapped[dict[str, Any]]
    body_hash: Mapped[str] = mapped_column(Text)

    __table_args__ = (
        Index("ix_events_user_occurred", "user_id", "occurred_at"),
        Index("ix_events_loan", "loan_id", postgresql_where=text("loan_id IS NOT NULL")),
    )


class Outbox(Base):
    __tablename__ = "outbox"
    id: Mapped[int] = mapped_column(BigInteger, Identity(), primary_key=True)
    event_id: Mapped[UUID] = mapped_column(ForeignKey("events.event_id"), unique=True)
    created_at: Mapped[datetime] = mapped_column(server_default=func.now())
    published_at: Mapped[datetime | None]

    __table_args__ = (Index("ix_outbox_unpublished", "id", postgresql_where=text("published_at IS NULL")),)


class FeatureVector(Base):
    __tablename__ = "feature_vectors"
    id: Mapped[UUID] = mapped_column(primary_key=True)
    user_id: Mapped[UUID]
    as_of: Mapped[datetime]
    features: Mapped[dict[str, Any]]
    feature_set_version: Mapped[str] = mapped_column(Text)
    created_at: Mapped[datetime] = mapped_column(server_default=func.now())

    __table_args__ = (Index("ix_feature_vectors_user_asof", "user_id", "as_of"),)


class ScoreSnapshot(Base):
    __tablename__ = "score_snapshots"
    id: Mapped[UUID] = mapped_column(primary_key=True)
    user_id: Mapped[UUID]
    as_of: Mapped[datetime]
    created_at: Mapped[datetime] = mapped_column(server_default=func.now())
    krs: Mapped[int] = mapped_column(SmallInteger)
    pd: Mapped[float] = mapped_column(Float)
    band: Mapped[str] = mapped_column(Text)
    aura: Mapped[int] = mapped_column(SmallInteger)
    tier: Mapped[str] = mapped_column(Text)
    fresh_spawn: Mapped[bool] = mapped_column(Boolean)
    streak: Mapped[int] = mapped_column(Integer)
    features: Mapped[dict[str, Any]]
    points: Mapped[dict[str, Any]]
    reason_codes: Mapped[dict[str, Any]]
    knockouts: Mapped[dict[str, Any]]
    limit_reco: Mapped[dict[str, Any]]
    # the exact event set this score was computed from, so it can be replayed
    input_event_ids: Mapped[list[UUID]] = mapped_column(ARRAY(PgUUID(as_uuid=True)))
    scorecard_version: Mapped[str] = mapped_column(Text)
    policy_version: Mapped[str] = mapped_column(Text)
    config_hash: Mapped[str] = mapped_column(Text)
    trigger_event_id: Mapped[UUID | None]

    __table_args__ = (
        Index("ix_score_snapshots_user_asof", "user_id", "as_of"),
        CheckConstraint("krs BETWEEN 0 AND 1000", name="krs_range"),
        CheckConstraint("aura BETWEEN 0 AND 100", name="aura_range"),
        CheckConstraint("pd > 0 AND pd < 1", name="pd_range"),
    )


class LimitLadderState(Base):
    """Latest ladder position per user, for ops views. Derived from the latest snapshot; the source of truth is the
    event log (the ladder is recomputed on every score)."""

    __tablename__ = "limit_ladder_state"
    user_id: Mapped[UUID] = mapped_column(ForeignKey("users.id"), primary_key=True)
    level: Mapped[int] = mapped_column(SmallInteger)
    clean_cycles_at_level: Mapped[int] = mapped_column(SmallInteger, server_default="0")
    frozen_until: Mapped[datetime | None]  # unused: a freeze ends on conditions (cure + clean cycles), not a date
    frozen: Mapped[bool] = mapped_column(Boolean, server_default=text("false"))
    last_step_up_at: Mapped[datetime | None]
    as_of: Mapped[datetime | None]
    snapshot_id: Mapped[UUID | None]
    updated_at: Mapped[datetime] = mapped_column(server_default=func.now())


class Decision(Base):
    """Append-only record of every precheck we answered and every decision the lending partner reported back,
    so our recommendation and their decision can be compared."""

    __tablename__ = "decisions"
    id: Mapped[UUID] = mapped_column(primary_key=True)
    kind: Mapped[str] = mapped_column(Text)  # precheck | outcome
    user_id: Mapped[UUID] = mapped_column(index=True)
    loan_id: Mapped[UUID | None] = mapped_column(index=True)
    precheck_id: Mapped[UUID | None]
    snapshot_id: Mapped[UUID | None]
    caller: Mapped[str] = mapped_column(Text)
    eligible: Mapped[bool | None] = mapped_column(Boolean)
    band: Mapped[str | None] = mapped_column(Text)
    recommended_limit: Mapped[int | None] = mapped_column(BigInteger)
    max_ticket: Mapped[int | None] = mapped_column(BigInteger)
    requested_amount: Mapped[int | None] = mapped_column(BigInteger)
    partner_decision: Mapped[str | None] = mapped_column(Text)
    partner_limit: Mapped[int | None] = mapped_column(BigInteger)
    knockouts: Mapped[dict[str, Any] | None]
    reason_codes: Mapped[dict[str, Any] | None]
    created_at: Mapped[datetime] = mapped_column(server_default=func.now())

    __table_args__ = (CheckConstraint("kind IN ('precheck', 'outcome')", name="decision_kind"),)


class ConfigVersion(Base):
    """Every scorecard + policy pair the service has run with, keyed by hash, so old snapshots stay replayable."""

    __tablename__ = "config_versions"
    hash: Mapped[str] = mapped_column(Text, primary_key=True)
    scorecard_version: Mapped[str] = mapped_column(Text)
    policy_version: Mapped[str] = mapped_column(Text)
    scorecard: Mapped[dict[str, Any]]
    policy: Mapped[dict[str, Any]]
    first_seen_at: Mapped[datetime] = mapped_column(server_default=func.now())


class Override(Base):
    __tablename__ = "overrides"
    id: Mapped[UUID] = mapped_column(primary_key=True)
    user_id: Mapped[UUID] = mapped_column(ForeignKey("users.id"), index=True)
    field: Mapped[str] = mapped_column(Text)
    value: Mapped[dict[str, Any]]
    reason: Mapped[str] = mapped_column(Text)
    maker_id: Mapped[UUID]
    checker_id: Mapped[UUID | None]
    status: Mapped[str] = mapped_column(Text, server_default="pending")
    created_at: Mapped[datetime] = mapped_column(server_default=func.now())
    decided_at: Mapped[datetime | None]
    expires_at: Mapped[datetime]

    __table_args__ = (CheckConstraint("checker_id IS NULL OR checker_id <> maker_id", name="maker_is_not_checker"),)


class FraudAlert(Base):
    """One open alert per (rule, student, vendor) at a time; new instances of the pattern merge into it."""

    __tablename__ = "fraud_alerts"
    id: Mapped[UUID] = mapped_column(primary_key=True)
    user_id: Mapped[UUID | None] = mapped_column(index=True)
    vendor_id: Mapped[UUID | None] = mapped_column(index=True)
    rule: Mapped[str] = mapped_column(Text)
    severity: Mapped[str] = mapped_column(Text)
    evidence: Mapped[dict[str, Any]]  # {"instances": [...]}: ids, amounts, times and counts only
    instance_keys: Mapped[list[str]] = mapped_column(ARRAY(Text), server_default="{}")
    status: Mapped[str] = mapped_column(Text, server_default="open", index=True)
    hold: Mapped[bool] = mapped_column(Boolean, server_default=text("false"))  # set the hold flag when raised
    flag: Mapped[str | None] = mapped_column(Text)  # the knockout flag set on confirmation, if any
    observed_at: Mapped[datetime]  # when the first instance became visible (event time)
    last_seen_at: Mapped[datetime]
    resolution_reason: Mapped[str | None] = mapped_column(Text)
    resolved_by: Mapped[UUID | None]
    lift_requested_by: Mapped[UUID | None]
    lift_reason: Mapped[str | None] = mapped_column(Text)
    lift_requested_at: Mapped[datetime | None]
    lifted_by: Mapped[UUID | None]
    lifted_at: Mapped[datetime | None]
    synthetic: Mapped[bool] = mapped_column(Boolean, server_default=text("false"))
    created_at: Mapped[datetime] = mapped_column(server_default=func.now())
    resolved_at: Mapped[datetime | None]

    __table_args__ = (
        CheckConstraint("user_id IS NOT NULL OR vendor_id IS NOT NULL", name="has_subject"),
        CheckConstraint("status IN ('open', 'confirmed', 'dismissed', 'lift_pending', 'lifted')", name="alert_status"),
        CheckConstraint("lifted_by IS NULL OR lifted_by <> lift_requested_by", name="lift_maker_is_not_checker"),
    )


class Spend(Base):
    """Read model of spend_made events, for checks that look across students (vendor surges)."""

    __tablename__ = "spends"
    event_id: Mapped[UUID] = mapped_column(primary_key=True)
    user_id: Mapped[UUID] = mapped_column(index=True)
    loan_id: Mapped[UUID]
    vendor_id: Mapped[UUID]
    amount: Mapped[int] = mapped_column(BigInteger)
    at: Mapped[datetime]
    synthetic: Mapped[bool] = mapped_column(Boolean, server_default=text("false"))

    __table_args__ = (Index("ix_spends_vendor_at", "vendor_id", "at"),)


class IdentityLink(Base):
    """Which accounts presented which identifier digest (device, payout account, phone). Never the raw value."""

    __tablename__ = "identity_links"
    kind: Mapped[str] = mapped_column(Text, primary_key=True)
    digest: Mapped[str] = mapped_column(Text, primary_key=True)
    user_id: Mapped[UUID] = mapped_column(primary_key=True, index=True)
    first_seen_at: Mapped[datetime]


class Consent(Base):
    __tablename__ = "consents"
    id: Mapped[UUID] = mapped_column(primary_key=True)  # the event_id that reported it
    user_id: Mapped[UUID] = mapped_column(index=True)
    purpose: Mapped[str] = mapped_column(Text)
    granted: Mapped[bool] = mapped_column(Boolean)
    at: Mapped[datetime]
    text_version: Mapped[str] = mapped_column(Text)


class AuditLog(Base):
    __tablename__ = "audit_log"
    id: Mapped[UUID] = mapped_column(primary_key=True)
    actor_id: Mapped[UUID]
    action: Mapped[str] = mapped_column(Text)
    target: Mapped[str] = mapped_column(Text)
    before: Mapped[dict[str, Any] | None]
    after: Mapped[dict[str, Any] | None]
    at: Mapped[datetime] = mapped_column(server_default=func.now())


class Outcome(Base):
    """One labelled loan per label version, with the score and features the loan had when it was decided (no
    leakage: computed only from events before the decision). Append-only: a new label definition is a new version."""

    __tablename__ = "outcomes"
    loan_id: Mapped[UUID] = mapped_column(ForeignKey("loans.id"), primary_key=True)
    label_version: Mapped[int] = mapped_column(SmallInteger, primary_key=True)
    observed_at: Mapped[datetime]  # when the label became known: the end of the label window
    bad_flag: Mapped[bool] = mapped_column(Boolean)
    user_id: Mapped[UUID] = mapped_column(index=True)
    decision_at: Mapped[datetime]
    due_date: Mapped[date]
    principal: Mapped[int] = mapped_column(BigInteger)
    worst_dpd: Mapped[int] = mapped_column(Integer)  # highest days past due inside the label window
    closure_type: Mapped[str | None] = mapped_column(Text)
    reason: Mapped[str] = mapped_column(Text)  # dpd | negative_closure | good
    krs: Mapped[int] = mapped_column(SmallInteger)  # at decision time
    pd: Mapped[float] = mapped_column(Float)
    band: Mapped[str] = mapped_column(Text)
    aura: Mapped[int] = mapped_column(SmallInteger)
    level: Mapped[str | None] = mapped_column(Text)
    features: Mapped[dict[str, Any]]  # at decision time
    config_hash: Mapped[str] = mapped_column(Text)
    synthetic: Mapped[bool] = mapped_column(Boolean, server_default=text("false"))
